// frontend/src/components/Search.js
import React, { useState, useEffect, useContext } from "react";
import axios from "../utils/axiosInstance";
import GeneralContext from "./GeneralContext";

const Search = () => {
  const [query, setQuery] = useState("");
  const [results, setResults] = useState([]);
  const { refreshWatchlist, watchlist } = useContext(GeneralContext);

  useEffect(() => {
    const delayDebounce = setTimeout(async () => {
      if (query.trim()) {
        try {
          const res = await axios.get(`/search?q=${query}`);
          setResults(res.data || []);
        } catch (err) {
          console.error(err);
        }
      } else {
        setResults([]);
      }
    }, 300);
    return () => clearTimeout(delayDebounce);
  }, [query]);

  const handleAdd = async (stock) => {
    try {
      await axios.post("/api/watchlist", stock);
      refreshWatchlist();
    } catch (err) {
      alert(err.response?.data?.message || "Failed to add");
    }
  };

  return (
    <div className="search-container">
      <input
        className="search"
        placeholder="Search eg: INFY, RELIANCE"
        value={query}
        onChange={(e) => setQuery(e.target.value)}
      />
      {results.length > 0 && (
        <ul className="search-dropdown">
          {results.map((stock, idx) => (
            <li className="search-item" key={idx}>
              <div>
                <strong>{stock.symbol}</strong> - {stock.name} ({stock.exchange}
                ) @ ₹{stock.price} ({stock.changePct}%)
              </div>
              <button
                className="add-btn"
                onClick={() => handleAdd(stock)}
                disabled={watchlist.some((s) => s.symbol === stock.symbol)}>
                {watchlist.some((s) => s.symbol === stock.symbol)
                  ? "Added"
                  : "Add"}
              </button>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

export default Search;
